import React from 'react';
import { Container, Typography, Paper, Grid, Box, Card, CardContent } from '@mui/material';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

const Dashboard = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  if (!currentUser) {
    return (
      <Container>
        <Typography>Please log in to view dashboard</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Welcome, {currentUser.email}!
      </Typography>
      <Typography variant="h6" color="textSecondary" gutterBottom>
        Role: {currentUser.role}
      </Typography>

      <Grid container spacing={3} sx={{ mt: 2 }}>
        {currentUser.role === 'student' && (
          <>
            <Grid item xs={12} md={6}>
              <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/institutions')}>
                <CardContent>
                  <Typography variant="h6">Browse Institutions</Typography>
                  <Typography color="textSecondary">
                    Discover higher learning institutions and their courses
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={6}>
              <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/jobs')}>
                <CardContent>
                  <Typography variant="h6">Find Jobs</Typography>
                  <Typography color="textSecondary">
                    Explore career opportunities from partner companies
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          </>
        )}

        {currentUser.role === 'institution' && (
          <Grid item xs={12} md={6}>
            <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/applications')}>
              <CardContent>
                <Typography variant="h6">View Applications</Typography>
                <Typography color="textSecondary">
                  Manage student applications and admissions
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        )}

        {currentUser.role === 'company' && (
          <Grid item xs={12} md={6}>
            <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/jobs')}>
              <CardContent>
                <Typography variant="h6">Post Jobs</Typography>
                <Typography color="textSecondary">
                  Create new job opportunities for graduates
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        )}
      </Grid>
    </Container>
  );
};

export default Dashboard;
